css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .7); position: relative; }
.loader::after { content: ''; position: absolute; bottom: 0; left: 0; width: 100%; height: 22%; border-radius: 4px 22% 4px 4px; background: linear-gradient(var(--accent-2), color-mix(in srgb, #000 32%, var(--accent-2))); }
.loader::before { content: ''; position: absolute; z-index: 2; bottom: 20%; right: 3%; width: 22%; height: 9%; background: color-mix(in srgb, #000 40%, var(--accent-2)); clip-path: polygon(0 0, 100% 0, 100% 100%, 90% 36%, 80% 100%, 70% 36%, 60% 100%, 50% 36%, 40% 100%, 30% 36%, 20% 100%, 10% 36%, 0 100%); }
.loader .roll { position: absolute; bottom: 20%; left: 7%; width: 44%; height: 62%; border-radius: 50%; background: conic-gradient(from 0deg, var(--accent) 0 47%, color-mix(in srgb, #000 26%, var(--accent)) 47% 50%, var(--accent) 50% 97%, color-mix(in srgb, #000 26%, var(--accent)) 97% 100%); box-shadow: inset 0 0 0 calc(var(--loader-size) * .075) color-mix(in srgb, #fff 66%, var(--accent-2)); animation: roll-spin calc(var(--loader-speed) * 2.4) linear infinite; }
.loader .roll::after { content: ''; position: absolute; inset: 34%; border-radius: 50%; background: color-mix(in srgb, #000 22%, var(--accent-2)); }
.loader span { position: absolute; bottom: 27%; left: 47%; height: 5%; border-radius: 1px; background: color-mix(in srgb, #fff 58%, var(--accent)); animation: pull-tape calc(var(--loader-speed) * 2.4) ease-in-out infinite; }
@keyframes roll-spin { to { transform: rotate(-360deg); } }
@keyframes pull-tape { 0% { width: 4%; } 66% { width: 44%; } 100% { width: 4%; } }
